function testReadStateFile(directory)
%TESTREADSTATEFILE Exercise HDF5 files generated by the C++ system tests.
powerflow = readStateFile(fullfile(directory, 'powerflow.h5'));
assert(isequal(powerflow.code, 0));
assert(powerflow.time_ns == int64(0));
assert(powerflow.source == 0 && powerflow.typecode == 0);
diag = readStateFile(fullfile(directory, 'solver-diagnostic.h5'));
assert(diag.time == 0.25 && diag.index == 7 && diag.source == 1);
assert(isequal(diag.data{1}, powerflow.data{1}));
mixed = readStateFile(fullfile(directory, 'mixed.h5'));
assert(isequal(mixed.source, [0 1 1]));
assert(isequal(mixed.typecode, [0 0 1]));
assert(mixed.data{3}.row == 0 && mixed.data{3}.col == 1 && mixed.data{3}.val == 0.75);
[state, jacobian, names] = loadJacState(fullfile(directory, 'jac-state.h5'));
assert(isequal(state, powerflow.data{1}));
assert(issparse(jacobian) && isequal(size(jacobian), [numel(state) numel(state)]));
assert(numel(names) == numel(state));
[jacData, jacNames] = readJacFile(fullfile(directory, 'jacobian.h5'));
assert(isequal(jacNames, names));
assert(jacData.rows == numel(state) && jacData.columns == numel(state));
for name = {'solver-run', 'dae-solver-run', 'cvode-solver-run', 'arkode-solver-run'}
    path = fullfile(directory, [name{1} '.h5']);
    if exist(path, 'file') ~= 2, continue; end
    run = readStateFile(path);
    assert(~isempty(run.data) && all(run.source == 1));
    assert(any(run.code == 0));
    frames = unique(run.frame);
    for ii = 1:numel(frames)
        selected = run.frame == frames(ii);
        assert(all(run.time_ns(selected) == run.time_ns(find(selected, 1))));
        assert(all(run.index(selected) == run.index(find(selected, 1))));
    end
end
solverJac = readStateFile(fullfile(directory, 'solver-jacobian.h5'));
assert(all(solverJac.typecode == 1));
assert(all(isfinite(solverJac.cj)));
dynamic = readStateFile(fullfile(directory, 'dynamic.h5'));
assert(isequal(dynamic.code, [0 1 0 1]));
assert(all(dynamic.time_ns == int64(123456789)));
assert(all(dynamic.frame == uint64([0 0 1 1])));
n = numel(dynamic.data{1});
assert(isequal(dynamic.data{1}, (0:n-1)' + 0.125));
assert(isequal(dynamic.data{2}, -(0:n-1)' - 0.25));
assert(dynamic.data{3}(1) == 123.5 && dynamic.data{4}(1) == -456.5);
selected = readStateFile(fullfile(directory, 'dynamic.h5'), 'Frame', uint64(1), 'Code', 0);
assert(numel(selected.data) == 1 && selected.data{1}(1) == 123.5);
meta = readStateFile(fullfile(directory, 'dynamic.h5'), 'MetadataOnly', true);
assert(all(cellfun(@isempty, meta.data)) && isequal(meta.frame, dynamic.frame));
[states, derivatives, times] = processCVODEStatefile(fullfile(directory, 'dynamic.h5'), false);
assert(isequal(states, [dynamic.data{1}.'; dynamic.data{3}.']));
assert(isequal(derivatives, [dynamic.data{2}.'; dynamic.data{4}.']));
assert(isequal(times, dynamic.time([1 3])));
periodic = readStateFile(fullfile(directory, 'periodic.h5'));
assert(numel(periodic.data) >= 4 && periodic.time_ns(end) >= int64(100000000));
typed = readStateFile(fullfile(directory, 'typed-records.h5'));
assert(typed.time_ns(1) == int64(9007199254740992) + int64(1));
assert(typed.index(1) == uint64(4294967297));
assert(isinf(typed.data{1}(3)) && isnan(typed.data{1}(4)));
assert(isinf(1 / typed.data{1}(2)) && 1 / typed.data{1}(2) < 0);
assert(typed.data{2}.rows == 3 && typed.data{2}.columns == 5);
assert(numel(typed.data{2}.val) == 9000 && typed.data{2}.val(8193) == 8192);
assert(strcmp(typed.data{3}{2}, '') && numel(typed.data{3}{4}) == 400);
assert(strcmp(typed.data{3}{3}, ['bus_' native2unicode(uint8([206 177]), 'UTF-8')]));
assert(typed.data{4}.rows == 4 && typed.data{4}.columns == 7 && isempty(typed.data{4}.val));
for name = {'cvode-paired-state', 'arkode-paired-state'}
    path = fullfile(directory, [name{1} '.h5']);
    if exist(path, 'file') ~= 2, continue; end
    paired = readStateFile(path);
    assert(isequal(paired.code, repmat([0 1 0], 1, numel(paired.code) / 3)));
    assert(paired.key(1) ~= paired.key(3));
    assert(paired.paired_key(1) == paired.key(3));
    [stateRows, derivativeRows] = processCVODEStatefile(path, false);
    assert(size(stateRows, 1) == numel(paired.code) / 3);
    assert(isequal(size(stateRows), size(derivativeRows)));
end
bad = [tempname(directory) '.h5'];
cleanup = onCleanup(@() delete(bad)); %#ok<NASGU>
copyfile(fullfile(directory, 'dynamic.h5'), bad);
h5writeatt(bad, '/', 'schema_version', uint32(2));
expectFormatError(bad);
copyfile(fullfile(directory, 'dynamic.h5'), bad, 'f');
h5write(bad, '/committed_records', intmax('uint64'));
expectFormatError(bad);
fid = fopen(bad, 'wb'); fwrite(fid, uint8('GDSTATE1')); fclose(fid);
expectFormatError(bad);
fprintf('GridDyn MATLAB HDF5 reader tests passed.\n');
end
function expectFormatError(path)
failed = false;
try, readStateFile(path);
catch exc
    assert(strcmp(exc.identifier, 'GridDyn:StateFileFormat')); failed = true;
end
assert(failed);
end
